#!/usr/bin/env python3
from pathlib import Path
import sys

p = Path(sys.argv[1])
s = p.read_text()

anchor = """    }).sort((left, right) => right.score - left.score);\n    const hybridRow = rows.find((row) => tempoClose(row.bpm, hybrid.bpm)) ?? rows[0];\n"""
insert = """    }).sort((left, right) => right.score - left.score);\n    // Research-only metrical-family expansion. These candidates DO NOT participate in selection.\n    // Reference BPM is never visible here; all evidence is signal-derived.\n    const metricalRatios = [\n        [0.5, '1:2'], [2, '2:1'],\n        [2 / 3, '2:3'], [3 / 2, '3:2'],\n        [3 / 4, '3:4'], [4 / 3, '4:3'],\n        [4 / 5, '4:5'], [5 / 4, '5:4'],\n        [3 / 5, '3:5'], [5 / 3, '5:3'],\n    ];\n    const expandedSeeds = [];\n    for (const seed of candidateSeeds) {\n        expandedSeeds.push({ bpm: seed.bpm, weight: seed.weight, transform: 'direct' });\n        for (const [ratio, label] of metricalRatios) {\n            const bpm = seed.bpm * ratio;\n            if (bpm >= 55 && bpm <= 220) expandedSeeds.push({ bpm, weight: seed.weight * 0.55, transform: label });\n        }\n    }\n    const expandedClusters = [];\n    for (const seed of expandedSeeds) {\n        let cluster = expandedClusters.find((item) => tempoClose(item.bpm, seed.bpm));\n        if (!cluster) { cluster = { bpm: seed.bpm, seeds: [] }; expandedClusters.push(cluster); }\n        cluster.seeds.push(seed);\n        const weightTotal = cluster.seeds.reduce((sum, item) => sum + item.weight, 0);\n        cluster.bpm = cluster.seeds.reduce((sum, item) => sum + item.bpm * item.weight, 0) / Math.max(0.000001, weightTotal);\n    }\n    const expandedRawRows = expandedClusters.map((cluster) => {\n        const bpm = cluster.bpm;\n        const supports = layerSpecs.map((layer) => normalizedCorrelationSupport(layer.values, envelope.hopSeconds, bpm));\n        const phase = phaseCoherenceAtBpm(peaks, bpm, 0).score;\n        const directVotes = layerEstimates.filter((layer) => layer.estimate && tempoClose(layer.estimate.bpm, bpm)).length / layerEstimates.length;\n        return { bpm, supports, phase, directVotes, cluster };\n    });\n    const expandedMaxPhase = Math.max(...expandedRawRows.map((row) => row.phase), 0.000001);\n    const researchMetricalCandidates = expandedRawRows.map((row) => {\n        const meanSupport = row.supports.reduce((sum, value) => sum + value, 0) / row.supports.length;\n        const medianSupport = median(row.supports);\n        const strongLayers = row.supports.filter((value) => value >= 0.8).length;\n        const phaseSupport = clamp01(row.phase / expandedMaxPhase);\n        const score = clamp01(0.4 * medianSupport + 0.25 * meanSupport + 0.25 * phaseSupport + 0.1 * row.directVotes);\n\n        // Higher-order metrical evidence: ask how well the candidate produces an actual repeatable\n        // beat grid, globally and across separated windows. This is intentionally measured before\n        // selection so rational cross-rhythms cannot win solely on autocorrelation.\n        const trackEnd = envelope.values.length * envelope.hopSeconds;\n        const grid = metricalGridSupportAtBpm(envelope, row.bpm, 0, trackEnd);\n        const layerGridSpecs = [\n            ['amplitude', envelope.amplitudeValues, envelope.frameOffsetSeconds],\n            ['low', envelope.lowPulseValues, envelope.hopSeconds / 2],\n            ['mid', envelope.midPulseValues, envelope.hopSeconds / 2],\n            ['hybrid', envelope.values, envelope.frameOffsetSeconds],\n            ['transient', envelope.transientValues, envelope.frameOffsetSeconds],\n            ['high', envelope.highPulseValues, envelope.hopSeconds / 2],\n        ];\n        const layerGrid = Object.fromEntries(layerGridSpecs.map(([name, values, frameOffset]) => {\n            const support = gridSupportForLayerAtOffset(values, envelope.hopSeconds, frameOffset, row.bpm, 0, trackEnd, grid.beatOffset);\n            return [name, support];\n        }));\n        const foundationGridScore = median(['amplitude', 'low', 'mid'].map((name) => layerGrid[name].score));\n        const foundationGridCoverage = median(['amplitude', 'low', 'mid'].map((name) => layerGrid[name].coverage));\n        const detailGridScore = median(['transient', 'high'].map((name) => layerGrid[name].score));\n        const detailGridCoverage = median(['transient', 'high'].map((name) => layerGrid[name].coverage));\n\n        const windows = [];\n        if (trackEnd >= 16) {\n            const windowLength = Math.min(24, Math.max(10, trackEnd / 5));\n            const count = trackEnd >= windowLength * 1.5 ? 4 : 2;\n            for (let wi = 0; wi < count; wi += 1) {\n                const start = count === 1 ? 0 : (wi * Math.max(0, trackEnd - windowLength)) / Math.max(1, count - 1);\n                const end = Math.min(trackEnd, start + windowLength);\n                if (end - start < 8) continue;\n                windows.push(metricalGridSupportAtBpm(envelope, row.bpm, start, end));\n            }\n        }\n        const windowScores = windows.map((item) => item.score);\n        const windowCoverages = windows.map((item) => item.coverage);\n        const windowJitters = windows.map((item) => Math.min(250, Number.isFinite(item.jitterMs) ? item.jitterMs : 250));\n        const stableWindows = windows.filter((item) => item.score >= 0.6 && item.coverage >= 0.55).length;\n\n        return {\n            bpm: Number(row.bpm.toFixed(3)), score: Number(score.toFixed(4)),\n            medianSupport: Number(medianSupport.toFixed(4)), meanSupport: Number(meanSupport.toFixed(4)),\n            phaseSupport: Number(phaseSupport.toFixed(4)), rawPhase: Number(row.phase.toFixed(6)),\n            strongLayers, directVotes: Number(row.directVotes.toFixed(4)),\n            seedWeight: Number(row.cluster.seeds.reduce((sum, item) => sum + item.weight, 0).toFixed(4)),\n            transforms: [...new Set(row.cluster.seeds.map((item) => item.transform))].sort(),\n            gridScore: Number(grid.score.toFixed(4)),\n            gridCoverage: Number(grid.coverage.toFixed(4)),\n            gridJitterMs: Number((Number.isFinite(grid.jitterMs) ? grid.jitterMs : 250).toFixed(3)),\n            foundationGridScore: Number(foundationGridScore.toFixed(4)),\n            foundationGridCoverage: Number(foundationGridCoverage.toFixed(4)),\n            detailGridScore: Number(detailGridScore.toFixed(4)),\n            detailGridCoverage: Number(detailGridCoverage.toFixed(4)),\n            amplitudeGridScore: Number(layerGrid.amplitude.score.toFixed(4)),\n            amplitudeGridCoverage: Number(layerGrid.amplitude.coverage.toFixed(4)),\n            lowGridScore: Number(layerGrid.low.score.toFixed(4)),\n            lowGridCoverage: Number(layerGrid.low.coverage.toFixed(4)),\n            midGridScore: Number(layerGrid.mid.score.toFixed(4)),\n            midGridCoverage: Number(layerGrid.mid.coverage.toFixed(4)),\n            transientGridScore: Number(layerGrid.transient.score.toFixed(4)),\n            transientGridCoverage: Number(layerGrid.transient.coverage.toFixed(4)),\n            highGridScore: Number(layerGrid.high.score.toFixed(4)),\n            highGridCoverage: Number(layerGrid.high.coverage.toFixed(4)),\n            windowGridMedian: Number((windowScores.length ? median(windowScores) : grid.score).toFixed(4)),\n            windowGridMin: Number((windowScores.length ? Math.min(...windowScores) : grid.score).toFixed(4)),\n            windowCoverageMedian: Number((windowCoverages.length ? median(windowCoverages) : grid.coverage).toFixed(4)),\n            windowCoverageMin: Number((windowCoverages.length ? Math.min(...windowCoverages) : grid.coverage).toFixed(4)),\n            windowJitterMedianMs: Number((windowJitters.length ? median(windowJitters) : Math.min(250, grid.jitterMs)).toFixed(3)),\n            windowStableFraction: Number((windows.length ? stableWindows / windows.length : 0).toFixed(4)),\n        };\n    }).sort((left, right) => right.score - left.score).slice(0, 32);\n    const hybridRow = rows.find((row) => tempoClose(row.bpm, hybrid.bpm)) ?? rows[0];\n"""
if anchor not in s:
    raise SystemExit('selector anchor not found')
s = s.replace(anchor, insert, 1)

anchor2 = """        runnerUpScore: Number((runnerUp?.score ?? 0).toFixed(4)),\n    };\n"""
rep2 = """        runnerUpScore: Number((runnerUp?.score ?? 0).toFixed(4)),\n        researchMetricalCandidates,\n    };\n"""
if anchor2 not in s:
    raise SystemExit('return anchor not found')
s = s.replace(anchor2, rep2, 1)

anchor3 = """            layeredPulseRunnerUpScore: layeredPulse.runnerUpScore,\n        },\n"""
rep3 = """            layeredPulseRunnerUpScore: layeredPulse.runnerUpScore,\n            researchMetricalCandidates: layeredPulse.researchMetricalCandidates,\n        },\n"""
if anchor3 not in s:
    raise SystemExit('diagnostics anchor not found')
s = s.replace(anchor3, rep3, 1)

p.write_text(s)
print(f'instrumented hierarchy evidence in {p}')
